import{_ as s,o as a,a as n,b as l}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"Mmad计算","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/mmad_compute"},{"text":"Gemm（废弃）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/Gemm_deprecated"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/Gemm_deprecated.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/Gemm_deprecated.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),d={name:"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/Gemm_deprecated.md"};function p(c,t,r,i,e,o){return a(),n("div",null,[...t[0]||(t[0]=[l(`<div><article class="markdown-body"><h1>Gemm（废弃）</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：不支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p><strong>该接口废弃，并将在后续版本移除，请不要使用该接口。</strong></p><p>根据输入的切分规则，将给定的两个输入张量做矩阵乘，输出至结果张量。将A和B两个输入矩阵乘法在一起，得到一个输出矩阵C。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>功能接口：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">U</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">S</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">Gemm</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">U</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src0</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">S</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">n</span><span class="p">,</span><span class="w"> </span><span class="n">GemmTiling</span><span class="w"> </span><span class="n">tiling</span><span class="p">,</span><span class="w"> </span><span class="kt">bool</span><span class="w"> </span><span class="n">partialsum</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="p">,</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">initValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">)</span>
</code></pre></div></li><li><p>切分方案计算接口：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="n">GemmTiling</span><span class="w"> </span><span class="n">GetGemmTiling</span><span class="p">(</span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">n</span><span class="p">)</span>
</code></pre></div></li></ul><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 接口参数说明</p><table><thead><tr><th>参数名称</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。<br><br><span data-filter="910">Atlas 训练系列产品，支持的TPosition为：CO1，CO2</span><br><span data-filter="310p">Atlas 推理系列产品AI Core，支持的TPosition为：CO1，CO2</span></td></tr><tr><td>src0</td><td>输入</td><td>源操作数，TPosition为A1。</td></tr><tr><td>src1</td><td>输入</td><td>源操作数，TPosition为B1。</td></tr><tr><td>m</td><td>输入</td><td>左矩阵Src0Local有效Height，范围：[1, 4096]。<br>注意：m可以不是16的倍数。</td></tr><tr><td>k</td><td>输入</td><td>左矩阵Src0Local有效Width、右矩阵Src1Local有效Height。<br>•当输入张量Src0Local的数据类型为float时，范围：[1, 8192]<br>•当输入张量Src0Local的数据类型为half时，范围：[1, 16384]<br>•当输入张量Src0Local的数据类型为int8_t时，范围：[1, 32768]<br><br>注意：k可以不是16的倍数。</td></tr><tr><td>n</td><td>输入</td><td>右矩阵Src1Local有效Width，范围：[1, 4096]。<br>注意：n可以不是16的倍数。</td></tr><tr><td>tiling</td><td>输入</td><td>切分规则，类型为GemmTiling，结构体具体定义为：<br><br>struct GemmTiling {<br> const uint32_t blockSize = 16;<br> LoopMode loopMode = LoopMode::MODE_NM;<br> uint32_t mNum = 0;<br> uint32_t nNum = 0;<br> uint32_t kNum = 0;<br> uint32_t roundM = 0;<br> uint32_t roundN = 0;<br> uint32_t roundK = 0;<br> uint32_t c0Size = 32;<br> uint32_t dtypeSize = 1;<br> uint32_t mBlockNum = 0;<br> uint32_t nBlockNum = 0;<br> uint32_t kBlockNum = 0;<br> uint32_t mIterNum = 0;<br> uint32_t nIterNum = 0;<br> uint32_t kIterNum = 0;<br> uint32_t mTileBlock = 0;<br> uint32_t nTileBlock = 0;<br> uint32_t kTileBlock = 0;<br> uint32_t kTailBlock = 0;<br> uint32_t mTailBlock = 0;<br> uint32_t nTailBlock = 0;<br> bool kHasTail = false;<br> bool mHasTail = false;<br> bool nHasTail = false;<br> bool kHasTailEle = false;<br> uint32_t kTailEle = 0;<br>};<br><br>参数说明请参考<a href="#table3">表3</a>。</td></tr><tr><td>partialsum</td><td>输入</td><td>当dst参数所在的TPosition为CO2时，通过该参数控制计算结果是否搬出。<br>•取值0：搬出计算结果；<br>•取值1：不搬出计算结果，可以进行后续计算。</td></tr><tr><td>initValue</td><td>输入</td><td>表示dst是否需要初始化。<br>•取值0：dst需要初始化，dst初始矩阵保存有之前结果，新计算结果会累加前一次Gemm计算结果。<br>•取值1：dst不需要初始化，dst初始矩阵中数据无意义，计算结果直接覆盖dst中的数据。</td></tr></tbody></table><p><strong>表2</strong> src0、src1和dst的数据类型组合</p><table><thead><tr><th>src0.dtype</th><th>src1.dtype</th><th>dst.dtype</th></tr></thead><tbody><tr><td>int8_t</td><td>int8_t</td><td>int32_t</td></tr><tr><td>half</td><td>half</td><td>float</td></tr><tr><td>half</td><td>half</td><td>half</td></tr></tbody></table><p><strong>表3</strong> GemmTiling结构内参数说明<a id="table3"></a></p><table><thead><tr><th>参数名称</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>blockSize</td><td>uint32_t</td><td>固定值，恒为16，一个维度内存放的元素个数。</td></tr><tr><td>loopMode</td><td>LoopMode</td><td>遍历模式，结构体具体定义为：<br><br><br>enum class LoopMode {<br> MODE_NM = 0,<br> MODE_MN = 1,<br> MODE_KM = 2,<br> MODE_KN = 3<br>};<br></td></tr><tr><td>mNum</td><td>uint32_t</td><td>M轴等效数据长度参数值，范围：[1, 4096]。</td></tr><tr><td>nNum</td><td>uint32_t</td><td>N轴等效数据长度参数值，范围：[1, 4096]。</td></tr><tr><td>kNum</td><td>uint32_t</td><td>K轴等效数据长度参数值。<br>•当输入张量Src0Local的数据类型为float时，范围：[1, 8192]。<br>•当输入张量Src0Local的数据类型为half时，范围：[1, 16384]。<br>•当输入张量Src0Local的数据类型为int8_t时，范围：[1, 32768]。</td></tr><tr><td>roundM</td><td>uint32_t</td><td>M轴等效数据长度参数值且以blockSize为倍数向上取整，范围：[1, 4096]。</td></tr><tr><td>roundN</td><td>uint32_t</td><td>N轴等效数据长度参数值且以blockSize为倍数向上取整，范围：[1, 4096]。</td></tr><tr><td>roundK</td><td>uint32_t</td><td>K轴等效数据长度参数值且以c0Size为倍数向上取整。<br>•当输入张量Src0Local的数据类型为float时，范围：[1, 8192]。<br>•当输入张量Src0Local的数据类型为half时，范围：[1, 16384]。<br>•当输入张量Src0Local的数据类型为int8_t时，范围：[1, 32768]。</td></tr><tr><td>c0Size</td><td>uint32_t</td><td>一个block的字节长度，范围：[16或者32]。</td></tr><tr><td>dtypeSize</td><td>uint32_t</td><td>传入的数据类型的字节长度，范围：[1, 2]。</td></tr><tr><td>mBlockNum</td><td>uint32_t</td><td>M轴Block个数，mBlockNum = mNum / blockSize。</td></tr><tr><td>nBlockNum</td><td>uint32_t</td><td>N轴Block个数，nBlockNum = nNum / blockSize。</td></tr><tr><td>kBlockNum</td><td>uint32_t</td><td>K轴Block个数，kBlockNum = kNum / blockSize。</td></tr><tr><td>mIterNum</td><td>uint32_t</td><td>遍历M轴维度数量，范围：[1, 4096]。</td></tr><tr><td>nIterNum</td><td>uint32_t</td><td>遍历N轴维度数量，范围：[1, 4096]。</td></tr><tr><td>kIterNum</td><td>uint32_t</td><td>遍历K轴维度数量，范围：[1, 4096]。</td></tr><tr><td>mTileBlock</td><td>uint32_t</td><td>M轴切分块个数，范围：[1, 4096]。</td></tr><tr><td>nTileBlock</td><td>uint32_t</td><td>N轴切分块个数，范围：[1, 4096]。</td></tr><tr><td>kTileBlock</td><td>uint32_t</td><td>K轴切分块个数，范围：[1, 4096]。</td></tr><tr><td>kTailBlock</td><td>uint32_t</td><td>K轴尾块个数，范围：[1, 4096]。</td></tr><tr><td>mTailBlock</td><td>uint32_t</td><td>M轴尾块个数，范围：[1, 4096]。</td></tr><tr><td>nTailBlock</td><td>uint32_t</td><td>N轴尾块个数，范围：[1, 4096]。</td></tr><tr><td>kHasTail</td><td>bool</td><td>K轴是否存在尾块。</td></tr><tr><td>mHasTail</td><td>bool</td><td>M轴是否存在尾块。</td></tr><tr><td>nHasTail</td><td>bool</td><td>N轴是否存在尾块。</td></tr><tr><td>kHasTailEle</td><td>bool</td><td>是否存在尾块元素。</td></tr><tr><td>kTailEle</td><td>uint32_t</td><td>K轴尾块元素，范围：[1, 4096]。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p><strong>表4</strong> src0、src1和dst的数据类型组合</p><table><thead><tr><th>src0.dtype</th><th>src1.dtype</th><th>dst.dtype</th></tr></thead><tbody><tr><td>int8_t</td><td>int8_t</td><td>int32_t</td></tr><tr><td>half</td><td>half</td><td>float</td></tr><tr><td>half</td><td>half</td><td>half</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>参数m，k，n可以不是16对齐，但因硬件原因，操作数dst，Src0Local和Src1Local的shape需满足对齐要求，即m方向，n方向要求向上16对齐，k方向根据操作数数据类型按16或32向上对齐。</li><li>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>该接口已废弃，请使用Mmad接口替代。</p></article></div>`,1)])])}const _=s(d,[["render",p]]);export{h as __pageData,_ as default};
